SELECT state FROM (SELECT TRIM(a."ShippingState") AS state, AVG(DATE_DIFF('day', created_dt::DATE, closed_dt::DATE)) AS avg_closure_days FROM (SELECT TRY_CAST(REPLACE(SUBSTR("CreatedDate",1,19), 'T', ' ') AS TIMESTAMP) AS created_dt, TRY_CAST(REPLACE(SUBSTR("ClosedDate",1,19), 'T', ' ') AS TIMESTAMP) AS closed_dt, CASE WHEN LEFT("AccountId",1) = '#' THEN SUBSTR("AccountId",2) ELSE "AccountId" END AS clean_account_id FROM "support_db"."Case" WHERE "ClosedDate" IS NOT NULL AND TRY_CAST(REPLACE(SUBSTR("ClosedDate",1,19), 'T', ' ') AS TIMESTAMP) >= DATE '2021-04-26' AND TRY_CAST(REPLACE(SUBSTR("ClosedDate",1,19), 'T', ' ') AS TIMESTAMP) <= DATE '2022-10-26') c JOIN "core_crm_db"."Account" a ON CASE WHEN LEFT(a."Id",1) = '#' THEN SUBSTR(a."Id",2) ELSE a."Id" END = c.clean_account_id WHERE a."ShippingState" IS NOT NULL GROUP BY TRIM(a."ShippingState")) t ORDER BY avg_closure_days ASC LIMIT 1